create extension if not exists pgcrypto;create type public.app_role as enum('admin','teacher','student');create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',email text,phone text,role public.app_role not null default 'student',created_at timestamptz default now());create table if not exists public.students(id uuid primary key default gen_random_uuid(),full_name text not null,phone text,email text,status text default 'active',notes text,created_at timestamptz default now());create table if not exists public.teachers(id uuid primary key default gen_random_uuid(),full_name text not null,phone text,email text,specialty text,status text default 'active',created_at timestamptz default now());create table if not exists public.courses(id uuid primary key default gen_random_uuid(),name text not null,description text,price_tmt numeric(12,2) default 0,duration_weeks int,created_at timestamptz default now());create table if not exists public.study_groups(id uuid primary key default gen_random_uuid(),name text not null,course_id uuid references public.courses(id),teacher_id uuid references public.teachers(id),schedule text,start_date date,status text default 'active',created_at timestamptz default now());create table if not exists public.attendance(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),group_id uuid references public.study_groups(id),lesson_date date default current_date,status text check(status in('present','absent','late','excused')),note text,created_at timestamptz default now());create table if not exists public.payments(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),amount_tmt numeric(12,2) not null check(amount_tmt>=0),paid_at date default current_date,method text default 'cash',period text,note text,created_at timestamptz default now());create table if not exists public.applications(id uuid primary key default gen_random_uuid(),full_name text not null,phone text not null,email text,notes text,status text default 'new',created_at timestamptz default now());create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;alter table public.profiles enable row level security;alter table public.students enable row level security;alter table public.teachers enable row level security;alter table public.courses enable row level security;alter table public.study_groups enable row level security;alter table public.attendance enable row level security;alter table public.payments enable row level security;alter table public.applications enable row level security;create policy "profile self or admin" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());create policy "admin profile edit" on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin students" on public.students for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin teachers" on public.teachers for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "course read" on public.courses for select to authenticated using(true);create policy "admin courses" on public.courses for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin groups" on public.study_groups for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin attendance" on public.attendance for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin payments" on public.payments for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "public applications insert" on public.applications for insert to anon,authenticated with check(true);create policy "admin applications" on public.applications for all to authenticated using(public.is_admin()) with check(public.is_admin());-- After creating first auth user, promote it: update public.profiles set role='admin' where email='YOUR_EMAIL';